namespace ndaw::v2 {class RecordingTestAccess {public:static te::HostedAudioDeviceInterface& host(Commands& c){auto& dm=c.engine.getDeviceManager();auto& h=dm.getHostedAudioDeviceInterface();te::HostedAudioDeviceInterface::Parameters p;p.sampleRate=48000;p.blockSize=256;p.inputChannels=1;p.outputChannels=2;h.initialise(p);dm.setAllWaveInputsToNumChannels(1);for(auto* i:dm.getWaveInputDevices()){i->setEnabled(true);i->setMonitorMode(te::InputDevice::MonitorMode::off);i->setOutputFormat("WAV file");i->setBitDepth(24);}dm.rescanMidiDeviceList();return h;}static void recordingEnabled(Commands& c,const std::string& id,bool enabled){c.engine.getDeviceManager().findMidiInputDeviceForID(juce::String(id))->recordingEnabled=enabled;}};}
namespace {
int checks=0;void check(bool b,const char* s){if(!b)throw std::runtime_error(s);++checks;std::cout<<"PASS "<<s<<std::endl;}
void settle(int ms=90){juce::MessageManager::getInstance()->runDispatchLoopUntil(ms);}
template<class F>void fails(F f,const char* s){bool failed=false;try{f();}catch(const std::exception&){failed=true;}check(failed,s);}
Json op(const char* c,Json a){return {{"command",c},{"args",a}};}Json run(Commands& c,Json ops){return c.commit(c.makePlan("human",ops));}
struct Feed {
    explicit Feed(te::HostedAudioDeviceInterface& h):thread([this,&h]{juce::AudioBuffer<float> b(2,256);juce::MidiBuffer midi;int64_t pos=0;while(!done){for(int i=0;i<256;++i)b.setSample(0,i,float(.08*std::sin(2*juce::MathConstants<double>::pi*1000*(pos+i)/48000.)));b.clear(1,0,256);midi.clear();auto start=anchor.load();if(start>=0){auto add=[&](int64_t offset,juce::MidiMessage m){auto at=start+offset;if(at>=pos&&at<pos+256)midi.addEvent(m,int(at-pos));};add(4800,juce::MidiMessage::noteOn(1,69,(juce::uint8)100));add(14400,juce::MidiMessage::noteOff(1,69));add(16800,juce::MidiMessage::controllerEvent(1,1,64));add(19200,juce::MidiMessage::pitchWheel(1,9000));add(21600,juce::MidiMessage::noteOn(1,72,(juce::uint8)90));add(31200,juce::MidiMessage::noteOff(1,72));}h.processBlock(b,midi);if(!midi.isEmpty()){std::lock_guard lock(mutex);for(auto e:midi)out.push_back(e.getMessage());}pos+=256;frame=pos;juce::Thread::sleep(2);}}){}
    ~Feed(){done=true;thread.join();}void schedule(){anchor=frame.load()+2048;}int noteOns(){std::lock_guard lock(mutex);int n=0;for(auto& m:out)n+=m.isNoteOn();return n;}std::atomic<bool> done{false};std::atomic<int64_t> frame{0},anchor{-1};std::mutex mutex;std::vector<juce::MidiMessage> out;std::thread thread;
};
void normaliseFloatingFacts(const Json& expected,Json& actual){if(expected.is_number_float()&&actual.is_number_float()){check(std::abs(expected.get<double>()-actual.get<double>())<1e-10,"reopened derived floating fact within 1e-10; integer samples remain exact");actual=expected;}else if(expected.is_object()&&actual.is_object()){for(auto it=expected.begin();it!=expected.end();++it)if(actual.contains(it.key()))normaliseFloatingFacts(it.value(),actual[it.key()]);}else if(expected.is_array()&&actual.is_array()&&expected.size()==actual.size()){for(size_t n=0;n<expected.size();++n)normaliseFloatingFacts(expected[n],actual[n]);}}
Json captured(const Json& track){for(const auto& c:track["clips"])if(c["notes"].size()==2)return c;throw std::runtime_error("captured two-note clip absent");}
}
