 auto tracks=q["tracks"];c.undo(receipt["plan_id"]);check(c.query()["tracks"][0]["clips"]==Json::array({old})&&c.query()["tracks"][1]["clips"].empty(),"one Undo removes both MIDI captures and preserves original");c.redo();check(c.query()["tracks"]==tracks,"Redo restores captured events, note IDs and native routing identically");
 auto saved=dir.getChildFile("midi.tracktionedit");c.save(saved);{Commands re(false);re.open(saved);auto reopenedClips=re.query()["tracks"][0]["clips"];auto expectedClips=tracks[0]["clips"];normaliseFloatingFacts(expectedClips,reopenedClips);check(reopenedClips==expectedClips,"save/reopen preserves MIDI notes and controllers");check(!re.query()["tracks"][0]["input"]["available"].get<bool>()&&re.query()["tracks"][0]["input"]["device"]==input,"missing MIDI device retains original stable reference");auto rendered=re.render(dir.getChildFile("recorded.wav"),0,96000);check(rendered["audio_verified"]&&rendered["peak"].get<double>()>1e-4&&rendered["frames"]==96000&&rendered["render_ms"].get<double>()<10000,"captured instrument MIDI renders actual 48 kHz PCM within fixed 10-second budget");}
 // No new scheduled events: report no_events and leave the previous Undo transaction intact.
 feed.anchor=-1;c.seek(0);auto history=Json::array({c.query()["can_undo"],c.query()["can_redo"]});c.record(dir);settle(180);c.stop();check(c.query()["last_recording"]["state"]=="no_events"&&c.query()["last_recording"]["clips"].empty(),"empty MIDI recording explicitly returns no_events");check(Json::array({c.query()["can_undo"],c.query()["can_redo"]})==history&&c.query()["tracks"]==tracks,"empty capture creates no fake clip or history transaction");
 c.undo(receipt["plan_id"]);check(c.query()["tracks"][0]["clips"]==Json::array({old}),"empty capture leaves previous transaction as the real Undo target");c.redo();
 auto stale=c.makePlan("human",Json::array({op("track.gain",{{"track",ins},{"db",-9}})}));c.configureMidiDevice("input",input,false);fails([&]{c.commit(stale);},"device configuration invalidates pre-existing Plan");settle(230);check(c.deviceStatus()["midi_configuration"]["state"]=="applied"&&!c.query()["tracks"][0]["input"]["available"].get<bool>(),"asynchronous native input disable has actual completion receipt");fails([&]{c.record(dir);},"missing armed MIDI device blocks capture");c.configureMidiDevice("input",input,true);settle(230);check(c.deviceStatus()["midi_configuration"]["state"]=="applied"&&c.query()["tracks"][0]["input"]["available"].get<bool>(),"native input enable rebuild restores actual target");
 auto audio=run(c,Json::array({op("track.create",{{"name","Audio"},{"type","audio"},{"ref","$a"}}),op("track.input",{{"track","$a"},{"device",wave}}),op("track.arm",{{"track","$a"},{"enabled",true}})}));settle();auto aq=c.query()["tracks"][2];fails([&]{c.makePlan("human",Json::array({op("track.output",{{"track",aq["id"]},{"target",output}})}));},"audio track cannot silently become MIDI output");c.seek(0);c.record(dir);feed.schedule();settle(600);c.stop();auto mixed=c.query()["last_recording"];check(mixed["state"]=="committed"&&mixed["files"].size()==1&&mixed["clips"].size()==3,"native mixed audio and two MIDI tracks captured in one transaction");c.undo(mixed["plan_id"]);check(c.query()["tracks"][2]["clips"].empty()&&c.query()["tracks"][0]["clips"].size()==2,"mixed recording Undo removes all newly captured media together");
